Since Next.js components (especially in Server Components) and standard React components live in isolation, you cannot rely on local state (`useState`) inside the individual `<Tooltip>` component to track which one is open. Instead, you must lift the state up to a Context Provider that wraps your entire application.

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to hold the global state. This will track the `isOpen` status and the `id` of the currently active tooltip.

`src/context/TooltipContext.tsx`

```tsx
'use client'; // Required for client-side interactivity

import React, { createContext, useContext, useState, ReactNode } from 'react';

// Define the shape of our context
interface TooltipContextType {
  openTooltip: (id: string) => void;
  closeTooltip: () => void;
  isOpen: boolean;
  activeId: string | null;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

interface TooltipProviderProps {
  children: ReactNode;
}

export const TooltipProvider = ({ children }: TooltipProviderProps) => {
  const [activeId, setActiveId] = useState<string | null>(null);

  const openTooltip = (id: string) => {
    // If clicking the same tooltip, toggle it off
    if (activeId === id) {
      setActiveId(null);
    } else {
      setActiveId(id);
    }
  };

  const closeTooltip = () => {
    setActiveId(null);
  };

  return (
    <TooltipContext.Provider
      value={{
        openTooltip,
        closeTooltip,
        isOpen: activeId !== null,
        activeId,
      }}
    >
      {children}
    </TooltipContext.Provider>
  );
};

// Custom hook to use the context anywhere
export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

