      e.preventDefault();
      const column = e.dataTransfer.getData('text/plain');
      const cells = row.querySelectorAll('td');
      const cellIndex = Array.from(cells).findIndex(cell => cell.dataset.column === column);
      const draggedData = cells[cellIndex].textContent;
      cells[cellIndex].textContent = cells[cellIndex].dataset.originalValue || draggedData;
    });
  });
</script>
