```javascript
// app/worker.js
import { parse } from 'papaparse'; // You will need to install this

self.onmessage = (e) => {
  const { file, delimiter } = e.data;

  // Read the file as text
  const reader = new FileReader();
  reader.onload = (event) => {
    const text = event.target.result;

    // Parse the CSV
    const result = parse(text, {
      delimiter: delimiter || ',',
      skipEmptyLines: true,
      header: true
    });

    // Send the parsed data back to the main thread
    self.postMessage({
      type: 'parsed',
      data: result.data,
      meta: result.meta
    });
  };
  reader.readAsText(file);
};
```

